from __future__ import annotations

from dataclasses import dataclass

from foreman.config import FactoryConfig
from foreman.models import Directive, FactoryState, ForemanResult, InterventionType
from foreman.responsibilities import ResponsibilityRegistry, builtin_registry


@dataclass(slots=True)
class FactoryPolicy:
    """Collect responsibility directives and select one under deterministic guardrails."""

    config: FactoryConfig
    responsibilities: ResponsibilityRegistry | None = None
    enforce_iteration_limit: bool = True

    def __post_init__(self) -> None:
        if self.responsibilities is None:
            candidates = builtin_registry(self.config)
            self.responsibilities = candidates.routed(candidates.global_ids())

    def _runtime_directive(
        self,
        state: FactoryState,
        action: InterventionType,
        reason: str,
        *,
        priority: int,
    ) -> Directive:
        return Directive(
            action=action,
            reason=reason,
            assessment_iteration=max(1, state.iteration),
            responsibility_id="foreman.runtime",
            priority=priority,
        )

    def configuration_error(self, state: FactoryState) -> Directive | None:
        for worker in state.workers:
            if worker.configuration_error:
                return self._runtime_directive(
                    state, InterventionType.ESCALATE, worker.configuration_error, priority=1000,
                )
        return None

    def evaluate(self, state: FactoryState, result: ForemanResult) -> ForemanResult:
        assert self.responsibilities is not None
        proposed = self.responsibilities.directives(state, result)

        configuration_error = self.configuration_error(state)
        if configuration_error is not None:
            proposed.append(configuration_error)

        # Hard iteration limits remain a runtime invariant, not responsibility semantics.
        if self.enforce_iteration_limit and state.iteration >= state.max_iterations:
            proposed.append(
                self._runtime_directive(
                    state,
                    InterventionType.ESCALATE,
                    "maximum Foreman iterations reached",
                    priority=950,
                )
            )

        if not proposed:
            selected = self._runtime_directive(
                state,
                InterventionType.CONTINUE,
                "active worker may continue",
                priority=0,
            )
        else:
            # `max` is stable, so responsibility order supplies deterministic tie-breaking.
            selected = max(
                proposed,
                key=lambda directive: (
                    directive.priority,
                    directive.confidence if directive.confidence is not None else -1.0,
                ),
            )

        if selected.action is InterventionType.RETRY_WORKER:
            retry_allowed = state.retry_count < self.config.max_retries
            worker_allowed = len(state.workers) < self.config.max_workers
            if not retry_allowed or not worker_allowed:
                selected = self._runtime_directive(
                    state,
                    InterventionType.ESCALATE,
                    "worker retry limit reached",
                    priority=selected.priority,
                )
                proposed.append(selected)
        elif selected.action is InterventionType.START_VERIFIER:
            if len(state.workers) >= self.config.max_workers:
                selected = self._runtime_directive(
                    state,
                    InterventionType.ESCALATE,
                    "verification needed but worker limit reached",
                    priority=selected.priority,
                )
                proposed.append(selected)
        elif selected.action is InterventionType.START_WORKER:
            if len(state.workers) >= self.config.max_workers:
                selected = self._runtime_directive(
                    state,
                    InterventionType.ESCALATE,
                    "worker limit reached before completion",
                    priority=selected.priority,
                )
                proposed.append(selected)

        return result.with_directives(proposed, selected)

    def decide(self, state: FactoryState, result: ForemanResult) -> Directive:
        evaluated = self.evaluate(state, result)
        assert evaluated.selected_directive is not None
        return evaluated.selected_directive

from __future__ import annotations

from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass
from typing import Any, Protocol

from foreman.models import Directive, FactoryState, ForemanResult


@dataclass(frozen=True, slots=True)
class Check:
    """A named semantic check contributed by one responsibility."""

    responsibility_id: str
    check_id: str
    instructions: str
    min_threshold: float | None = None
    evidence: tuple[str, ...] | None = None

    def __post_init__(self) -> None:
        if self.min_threshold is not None and not 0.0 <= self.min_threshold <= 1.0:
            raise ValueError("check min_threshold must be between 0 and 1")
        if self.evidence is not None:
            if not self.evidence or any(not provider.strip() for provider in self.evidence):
                raise ValueError("check evidence must contain non-empty provider ids")
            if len(self.evidence) != len(set(self.evidence)):
                raise ValueError("check evidence provider ids must be unique")

    @property
    def key(self) -> str:
        return f"{self.responsibility_id}__{self.check_id}"


@dataclass(frozen=True, slots=True)
class ResponsibilityRoute:
    """Responsibility-owned instructions for deciding whether it handles incoming work."""

    always: bool = True
    instructions: str | None = None
    threshold: float = 0.5

    def __post_init__(self) -> None:
        if not 0.0 <= self.threshold <= 1.0:
            raise ValueError("responsibility routing threshold must be between 0 and 1")
        if not self.always and not (self.instructions and self.instructions.strip()):
            raise ValueError("routed responsibilities require routing instructions")


class Responsibility(Protocol):
    """A logical unit that owns checks and proposes directives."""

    id: str

    def configured(self, settings: Mapping[str, Any]) -> Responsibility: ...

    def configured_checks(self, checks: Sequence[Check]) -> Responsibility: ...

    def route(self) -> ResponsibilityRoute: ...

    def checks(self) -> Sequence[Check]: ...

    def directives(self, state: FactoryState, result: ForemanResult) -> Sequence[Directive]: ...


class ResponsibilityRegistry:
    def __init__(
        self,
        responsibilities: Iterable[Responsibility],
        *,
        routes: dict[str, ResponsibilityRoute] | None = None,
        contexts: Mapping[str, str] | None = None,
    ) -> None:
        self._responsibilities = tuple(responsibilities)
        self._contexts = dict(contexts or {})
        ids = [responsibility.id for responsibility in self._responsibilities]
        if len(ids) != len(set(ids)):
            raise ValueError("responsibility ids must be unique")

        supplied_routes = routes or {}
        unknown_routes = set(supplied_routes) - set(ids)
        if unknown_routes:
            names = ", ".join(sorted(unknown_routes))
            raise ValueError(f"routing configured for unknown responsibilities: {names}")
        unknown_contexts = set(self._contexts) - set(ids)
        if unknown_contexts:
            raise ValueError(
                "context configured for unknown responsibilities: "
                + ", ".join(sorted(unknown_contexts))
            )
        self._routes: dict[str, ResponsibilityRoute] = {}
        for responsibility in self._responsibilities:
            route_factory = getattr(responsibility, "route", None)
            default_route = (
                route_factory() if callable(route_factory) else ResponsibilityRoute(always=True)
            )
            self._routes[responsibility.id] = supplied_routes.get(responsibility.id, default_route)

        check_keys: set[str] = set()
        checks: list[Check] = []
        for responsibility in self._responsibilities:
            responsibility_checks = tuple(responsibility.checks())
            if not responsibility_checks:
                raise ValueError(f"responsibility {responsibility.id!r} has no checks")
            for check in responsibility_checks:
                if check.responsibility_id != responsibility.id:
                    raise ValueError(
                        f"check {check.check_id!r} belongs to {check.responsibility_id!r}, "
                        f"not {responsibility.id!r}"
                    )
                if check.key in check_keys:
                    raise ValueError(f"duplicate check key: {check.key}")
                check_keys.add(check.key)
                checks.append(check)
        self._checks = tuple(checks)

    @property
    def responsibilities(self) -> tuple[Responsibility, ...]:
        return self._responsibilities

    def checks(self) -> tuple[Check, ...]:
        return self._checks

    def route_for(self, responsibility_id: str) -> ResponsibilityRoute:
        try:
            return self._routes[responsibility_id]
        except KeyError as error:
            raise KeyError(f"unknown responsibility: {responsibility_id}") from error

    def global_ids(self) -> tuple[str, ...]:
        return tuple(
            responsibility.id
            for responsibility in self._responsibilities
            if self._routes[responsibility.id].always
        )

    def context_for(self, responsibility_id: str) -> str | None:
        return self._contexts.get(responsibility_id)

    def routed(self, responsibility_ids: Iterable[str]) -> ResponsibilityRegistry:
        selected = set(responsibility_ids)
        known = {responsibility.id for responsibility in self._responsibilities}
        unknown = selected - known
        if unknown:
            raise ValueError(f"unknown routed responsibilities: {', '.join(sorted(unknown))}")
        responsibilities = [
            responsibility
            for responsibility in self._responsibilities
            if responsibility.id in selected
        ]
        return ResponsibilityRegistry(
            responsibilities,
            routes={
                responsibility.id: self._routes[responsibility.id]
                for responsibility in responsibilities
            },
            contexts={key: value for key, value in self._contexts.items() if key in selected},
        )

    def repository_instruction_files(self) -> tuple[str, ...]:
        files: list[str] = []
        for responsibility in self._responsibilities:
            configured = getattr(responsibility, "instruction_files", ())
            for filename in configured:
                if filename not in files:
                    files.append(filename)
        return tuple(files)

    def directives(self, state: FactoryState, result: ForemanResult) -> list[Directive]:
        proposals: list[Directive] = []
        for responsibility in self._responsibilities:
            for directive in responsibility.directives(state, result):
                if directive.responsibility_id != responsibility.id:
                    raise ValueError(
                        f"directive belongs to {directive.responsibility_id!r}, "
                        f"not {responsibility.id!r}"
                    )
                proposals.append(directive)
        return proposals
